  s.Master=.4f;s.Muted=true;s.Save(pth);t=Settings.Load(pth);Check(t.Muted&&t.Master==.4f&&t.MusicGain==0&&t.EffectsGain==0,"master volume and mute persistence");t.Muted=false;Check(Math.Abs(t.MusicGain-t.Music*.4f)<.0001f&&Math.Abs(t.EffectsGain-t.Effects*.4f)<.0001f,"unmute restores separate channel levels");File.Delete(pth);
  a=Fresh();a.Score=1499;a.OfferUpgrade(.1f);Check(!a.Entities.Exists(delegate(Entity v){return v.Kind=="upgrade";}),"no core before milestone");a.Score=1500;a.OfferUpgrade(.1f);Entity core=a.Entities.Find(delegate(Entity v){return v.Kind=="upgrade";});Check(core!=null&&core.Type==1&&a.Tier==0,"milestone offers optional core without automatic transformation");a.OfferUpgrade(20);Check(a.Entities.FindAll(delegate(Entity v){return v.Kind=="upgrade";}).Count==1,"only one offered core at once");a.Ammo=100;a.Health=50;a.CollectUpgrade(core);if(a.PendingTier>0)a.ChooseUpgrade(0);Check(a.Tier==1&&a.Ammo==180&&a.Health==65&&a.Invulnerable>0,"core transforms and grants supplies/protection");a.CollectUpgrade(core);if(a.PendingTier>0)a.ChooseUpgrade(0);Check(a.Ammo==180&&a.Tier==1,"core cannot be collected twice");
  a.Score=5000;a.OfferUpgrade(20);core=a.Entities.Find(delegate(Entity v){return v.Kind=="upgrade"&&!v.Dead;});Check(core!=null&&core.Type==2,"second milestone offers next hull");a.CollectUpgrade(core);if(a.PendingTier>0)a.ChooseUpgrade(0);a.Score=11000;a.OfferUpgrade(20);core=a.Entities.Find(delegate(Entity v){return v.Kind=="upgrade"&&!v.Dead;});a.CollectUpgrade(core);if(a.PendingTier>0)a.ChooseUpgrade(0);Check(a.Tier==3,"third milestone reaches Dreadstar");a.Entities.Clear();a.OfferUpgrade(30);Check(a.Entities.Count==0,"final hull has no further upgrade offers");
  a=Fresh();a.Score=1500;a.OfferUpgrade(.1f);a.Entities.Clear();a.OfferUpgrade(20);Check(a.Entities.Exists(delegate(Entity v){return v.Kind=="upgrade";}),"missed optional upgrade can be offered again");
