  a=Fresh();Entity victim=a.Add("enemy",new V(480,300),10,22);a.Add("bullet",victim.P,1.5f,5);a.Step(.01f,new V(),aim,false,false);Check(victim.HP==8.5f,"heavy cannon damage applied");
  a=Fresh();a.Tier=2;a.Time=48;a.Step(.01f,new V(),aim,false,false);Check(a.Level==1&&a.Tier==2,"ship evolution persists through sector transition");a.Invulnerable=0;a.Damage(15);Check(a.Tier==2,"damage does not remove earned hull");
  for(int stage=0;stage<5;stage++){a=new World(stage,7);Check(a.Add("enemy",new V(),3,22).Stage==stage,"sector "+stage+" enemy appearance assigned");}
  using(Audio silent=new Audio()){Check(silent.Music==0&&silent.Effects==0,"audio starts silent until saved volume and mute state apply");}
  RunFleetChecks(root);RunFleetCampaignMatrix(root);results.Add(count+" gameplay/settings assertions passed.");
  // Entire normal-speed simulation: pilot auto-repairs to exercise progression reliably.
  a=new World(0,93);float elapsed=0;while(!a.Won&&elapsed<900){if(a.PendingTier>0)a.ChooseUpgrade(a.Level%3);Entity target=null;float best=float.MaxValue;foreach(Entity v in a.Entities){if(v.P.Y>0&&a.Targetable(v)){float d=(v.P-a.Player).Length;if(d<best){best=d;target=v;}}}a.Step(1f/60,new V(),target==null?aim:target.P,true,false);if(a.Health<40)a.Health=100;elapsed+=1f/60;}
  Check(a.Won,"full campaign soak victory");results.Add("Full deterministic campaign soak: victory at "+elapsed.ToString("F1")+" simulated seconds; shots="+a.Shots+", kills="+a.Kills+", damage="+a.DamageEvents+". QA auto-repair enabled; not an unaided difficulty test.");
  using(Art art=new Art())using(Bitmap bmp=new Bitmap(960,780))using(Graphics g=Graphics.FromImage(bmp)){World stress=Fresh();for(int i=0;i<65;i++){Entity v=stress.Add(i%3==0?"rock":"enemy",new V(40+i*13,150+i%7*65),3,24);v.Type=i%4;}for(int i=0;i<30;i++)stress.Burst(new V(200+i*18,400),i%5,20);Stopwatch sw=Stopwatch.StartNew();for(int i=0;i<180;i++){g.DrawImageUnscaled(art.Background,0,0);art.DrawWorld(g,stress,i/60f);}sw.Stop();results.Add("Offscreen 960x780 stress draw (65 entities, 600 particles): "+(sw.Elapsed.TotalMilliseconds/180).ToString("F2")+" ms/frame; display presentation excluded.");}
  results.Add("Environment: "+Environment.OSVersion+"; "+Environment.Version+"; "+(Environment.Is64BitProcess?"x64":"x86")+"; CPU: "+Environment.GetEnvironmentVariable("PROCESSOR_IDENTIFIER"));File.WriteAllLines(Path.Combine(root,"selftest-results.txt"),results);
